from datetime import datetime, timedelta
from typing import Dict, Any, Optional
import jwt
from auth.schemas import TokenPair, TokenPayload
from auth.exceptions import TokenExpiredError, InvalidTokenError

class JWTManager:
    """Manages issuance, verification, and revocation of asymmetric JWT tokens."""
    def __init__(self, secret_key: str, algorithm: str = 'HS256', access_ttl_minutes: int = 15, refresh_ttl_days: int = 7):
        self.secret_key = secret_key
        self.algorithm = algorithm
        self.access_ttl = timedelta(minutes=access_ttl_minutes)
        self.refresh_ttl = timedelta(days=refresh_ttl_days)
        self._revoked_tokens = set()

    def create_token_pair(self, user_id: str, claims: Optional[Dict[str, Any]] = None) -> TokenPair:
        now = datetime.utcnow()
        access_exp = now + self.access_ttl
        refresh_exp = now + self.refresh_ttl
        access_payload = {'sub': user_id, 'exp': access_exp, 'iat': now, 'type': 'access', **(claims or {})}
        refresh_payload = {'sub': user_id, 'exp': refresh_exp, 'iat': now, 'type': 'refresh'}
        access_tok = jwt.encode(access_payload, self.secret_key, algorithm=self.algorithm)
        refresh_tok = jwt.encode(refresh_payload, self.secret_key, algorithm=self.algorithm)
        return TokenPair(access_token=access_tok, refresh_token=refresh_tok, expires_in=int(self.access_ttl.total_seconds()))

    def verify_token(self, token: str) -> TokenPayload:
        if token in self._revoked_tokens:
            raise InvalidTokenError('Token has been revoked')
        try:
            payload = jwt.decode(token, self.secret_key, algorithms=[self.algorithm])
            return TokenPayload(user_id=payload['sub'], expires_at=payload['exp'], token_type=payload.get('type', 'access'))
        except jwt.ExpiredSignatureError:
            raise TokenExpiredError('JWT signature has expired')
        except jwt.PyJWTError as e:
            raise InvalidTokenError(f'Malformed token: {e}')

    def revoke_token(self, token: str) -> None:
        self._revoked_tokens.add(token)

