import asyncio
from typing import Dict, List, Callable, Coroutine
from messaging.models import EventEnvelope
from messaging.dead_letter import DeadLetterQueue

class EventBus:
    """Asynchronous in-memory event bus with retry logic and dead-letter queue."""
    def __init__(self, max_retries: int = 3, dlq: DeadLetterQueue = None):
        self.subscribers: Dict[str, List[Callable[[EventEnvelope], Coroutine]]] = {}
        self.max_retries = max_retries
        self.dlq = dlq or DeadLetterQueue()

    def subscribe(self, topic: str, handler: Callable[[EventEnvelope], Coroutine]) -> None:
        self.subscribers.setdefault(topic, []).append(handler)

    async def publish(self, event: EventEnvelope) -> None:
        handlers = self.subscribers.get(event.topic, [])
        for handler in handlers:
            asyncio.create_task(self._dispatch_with_retry(handler, event))

    async def _dispatch_with_retry(self, handler, event: EventEnvelope):
        for attempt in range(1, self.max_retries + 1):
            try:
                await handler(event)
                return
            except Exception as exc:
                event.retry_count = attempt
                if attempt == self.max_retries:
                    await self.dlq.route_to_dlq(event, reason=str(exc))
                else:
                    await asyncio.sleep(2 ** attempt)

