from typing import List, Optional
from database.models import UserRecord

class UserRepository:
    """Data access repository for UserRecord persistence operations."""
    def __init__(self, session):
        self.session = session

    async def get_by_id(self, user_id: str) -> Optional[UserRecord]:
        """Retrieves a single user by primary UUID key."""
        return await self.session.get(UserRecord, user_id)

    async def find_by_email(self, email: str) -> Optional[UserRecord]:
        """Executes query filtering by unique email address."""
        result = await self.session.execute(
            "SELECT * FROM users WHERE email = :email", {'email': email}
        )
        return result.scalars().first()

    async def create(self, user: UserRecord) -> UserRecord:
        """Adds a new user instance to the pending transaction session."""
        self.session.add(user)
        await self.session.flush()
        return user

