from langgraph.graph import StateGraph, START, END
from workflow.state import AgentState

class MultiAgentCoordinator:
    """Orchestrates routing between Researcher and Writer agents."""
    def __init__(self):
        builder = StateGraph(AgentState)
        builder.add_node('researcher', self.research_node)
        builder.add_node('writer', self.writer_node)
        builder.add_edge(START, 'researcher')
        builder.add_conditional_edges('researcher', self.should_continue, {'continue': 'writer', 'end': END})
        builder.add_edge('writer', END)
        self.graph = builder.compile()

    def research_node(self, state: AgentState):
        return {'research_notes': 'Gathered findings'}

    def writer_node(self, state: AgentState):
        return {'final_article': 'Synthesized report'}

    def should_continue(self, state: AgentState):
        return 'continue' if state.get('research_notes') else 'end'

