class QueueSaturatedException(Exception):
    """Raised when in-flight tasks exceed maximum watermarks."""

class BackpressureController:
    def __init__(self, max_inflight: int = 100):
        self.max_inflight = max_inflight
        self.inflight_count = 0
    def can_accept(self) -> bool:
        return self.inflight_count < self.max_inflight
    def record_start(self):
        self.inflight_count += 1
    def record_finish(self):
        self.inflight_count = max(0, self.inflight_count - 1)

